<script setup lang="ts">
/**
 * Equal-track grid for card fields, stat rows and form pairs (`design/components/grid.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/grid.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { spacingAttrs, type LayoutPatch, type SpaceStep } from '@polymorph/vue'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type GridAlign = NonNullable<GridProps['align']>

export type GridColumns = NonNullable<GridProps['columns']>

export type GridElement = NonNullable<GridProps['as']>

export interface GridProps {
  align?: 'stretch' | 'start' | 'center' | 'end'
  as?: 'div' | 'section' | 'ul'
  columns?: 1 | 2 | 3 | 4 | 6 | 12
  gap?: SpaceStep
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
}

defineOptions({ name: 'Grid', inheritAttrs: false })

withDefaults(defineProps<GridProps>(), { align: 'stretch', as: 'div', columns: 2 })
defineSlots<{ default?: (props: Record<string, never>) => unknown }>()
</script>

<template>
  <component
    :is="as"
    v-bind="spacingAttrs({ gap, p, px, py, patch })"
    :class="[styles.layout, styles.grid]"
    :data-columns="String(columns)"
    :data-align="align"
    data-member="grid"
  >
    <slot />
  </component>
</template>
